lemma prod_comp (X : Type*) [AddCommMonoid X] [Module A X] {π : Representation A G X}
    (f : IntertwiningMap ρ σ) (g₁ : IntertwiningMap σ τ) (g₂ : IntertwiningMap σ π) :
    (prod g₁ g₂).comp f = prod (g₁.comp f) (g₂.comp f)

