lemma coind₁Map_comp_coind₁ResMap (φ : H →ₜ* G) {σ : ContRepresentation R H U}
    (f : π.restrict φ →ⁱL π') (g : π' →ⁱL σ) :
    (coind₁Map g).comp (coind₁ResMap φ f) = coind₁ResMap φ (g.comp f)

