    F f₁ φ = F f₂ (h ▸ φ)

theorem congr {f₁ f₂ : G →* H} (h : f₁ = f₂) {φ : res f₁ A ⟶ B} {T : Type*}
    (F : (f : G →* H) → (φ : res f A ⟶ B) → T) :
    F f₁ φ = F f₂ (h ▸ φ)

